-- Clarify optional packaging for new events; existing mission records stay intact.
create or replace function private.mission_plan_cards() returns jsonb language sql immutable set search_path='' as $$
 select '[{"idx":0,"title":"The Locked Archive","minutes":20,"max_points":100,"instructions":"Work in three teams to decode Signals, Plotting and Registry evidence. Combine your digits in that order and explain your reasoning to your flight NCO. The NCO checks the existing code and authorises opening your sealed ARCHIVE envelope to recover its access slip. There is one ARCHIVE envelope per flight. Your NCO retains CASE RAVEN until the Evidence Room begins. Keep clues within your flight. Phones away unless an NCO asks otherwise.","equipment":"Four sealed ARCHIVE envelopes with one access slip each; three printed clue lanes per flight, response sheets and pens. Staff retain CASE RAVEN and FINAL REVIEW papers until their stages. Envelopes for those papers are optional; wax-style seals are optional decoration."},{"idx":1,"title":"The Evidence Room: Case investigation","minutes":20,"max_points":125,"instructions":"A fictional classified file called RAVEN has been stolen. Compare the witness statement, badge register, door log, clock notice and storage records. Identify the suspect, theft time, exact hiding place, false claim and the evidence chain. Submit one flight response. These fictional characters have no connection to players\u2019 secret roles.","equipment":"Printed case packs, response sheet and pens. Staff retain Final Review papers until the later activity; a separate envelope is optional."},{"idx":2,"title":"The Evidence Room: Final Review","minutes":12,"max_points":100,"instructions":"Reopen the same case. Compare the new evidence with the original file. Decide which new report is false, explain why and identify who submitted it. State whether your original conclusion changes. Submit one final flight response.","equipment":"Retained case papers, staff-held final-review papers, response sheet and pens. A FINAL REVIEW envelope is optional."}]'::jsonb;
$$;
revoke all on function private.mission_plan_cards() from public,anon,authenticated;
